<?php
namespace App\Http\Controllers;
use App\Http\Requests\ExpenseRequest; use App\Models\{Expense,Budget}; use Illuminate\Validation\ValidationException;
class ExpenseController extends Controller { public function create(){return view('expenses.form',['expense'=>new Expense,'budgets'=>Budget::latest()->get()]);} public function store(ExpenseRequest $request){$data=$request->validated();$this->ensureInPeriod($data);Expense::create($data);return redirect()->route('budgets.show',$data['budget_id'])->with('success','Expense created.');} public function edit(Expense $expense){return view('expenses.form',['expense'=>$expense,'budgets'=>Budget::latest()->get()]);} public function update(ExpenseRequest $request,Expense $expense){$data=$request->validated();$this->ensureInPeriod($data);$expense->update($data);return redirect()->route('budgets.show',$data['budget_id'])->with('success','Expense updated.');} public function destroy(Expense $expense){$budget=$expense->budget_id;$expense->delete();return redirect()->route('budgets.show',$budget)->with('success','Expense deleted.');} private function ensureInPeriod(array $data): void {$budget=Budget::findOrFail($data['budget_id']);$date=\Carbon\Carbon::parse($data['expense_date']);if($date->lt($budget->period_start)||$date->gt($budget->period_end))throw ValidationException::withMessages(['expense_date'=>'The expense date must be within the budget period.']);} }
